def _require(condition, message):
    if not condition:
        raise ContractError(message)


def _finite(value, label, positive=False):
    value = float(value)
    _require(math.isfinite(value) and (not positive or value > 0),
             label + " must be " + ("positive and " if positive else "") + "finite")
    return value


def _unit_level(matrix, label):
    """Reject effective scale, reflection, shear and tilt, including parents."""
    _require(all(math.isfinite(v) for row in matrix for v in row),
             label + ": non-finite transform")
    columns = [matrix.to_3x3().col[i] for i in range(3)]
    tolerance = 2.e-6
    _require(all(abs(v.length - 1.) <= tolerance for v in columns)
             and all(abs(columns[i].dot(columns[j])) <= tolerance
                     for i in range(3) for j in range(i)),
             label + ": effective transform must have unit scale and no shear")
    _require(abs(matrix.to_3x3().determinant() - 1.) <= 4.e-6,
             label + ": reflected transforms are unsupported")
    _require((columns[2] - Vector((0., 0., 1.))).length <= tolerance,
             label + ": source/controller frame must be level with Z up")


def _sources(controller):
    settings = controller.st_network
    selected, seen = [], set()

    def add(obj, origin):
        key = obj.as_pointer()
        _require(key not in seen, f"{obj.name}: duplicate source from {origin}")
        seen.add(key)
        _require(obj == controller or not obj.st_network.enabled,
                 f"{obj.name}: another network controller cannot be an input")
        _require(not obj.st_generated_controller,
                 f"{obj.name}: generated output/internal carrier cannot be a source")
        _require(obj.instance_type == "NONE",
                 f"{obj.name}: source collection instances are unsupported; use real objects")
        _require(obj.type == "MESH", f"{obj.name}: source must be an edge-only mesh")
        _require(obj.st_source_controller == controller,
                 f"{obj.name}: source belongs to a different or unassigned network")
        _require(not obj.modifiers or obj == controller,
                 f"{obj.name}: authored source modifiers are unsupported; edit the base mesh")
        _require(not obj.constraints,
                 f"{obj.name}: constrained source placement is unsupported")
        parent = obj.parent
        while parent:
            _require(not parent.st_generated_controller,
                     f"{obj.name}: source depends on generated output through its parent")
            parent = parent.parent
        _unit_level(obj.matrix_world, obj.name)
        selected.append(obj)

    if settings.use_controller_mesh:
        add(controller, "controller base mesh")
    if settings.grouped_object:
        _require(settings.grouped_object != controller,
                 "Use the explicit controller-base-mesh option, not a self input")
        add(settings.grouped_object, "grouped input")
    collection_seen = set()

    def visit(collection):
        pointer = collection.as_pointer()
        _require(pointer not in collection_seen,
                 f"{collection.name}: repeated/cyclic source collection dependency")
        collection_seen.add(pointer)
        for obj in collection.objects:
            _require(obj != controller, "Controller cannot be inside the input collection")
            add(obj, collection.name)
        for child in collection.children:
            visit(child)

    if settings.source_collection:
        visit(settings.source_collection)
    _require(bool(selected), "No source meshes selected")
    # Shared mesh datablocks imply duplicated complete Section IDs. Diagnosing
    # this explicitly is clearer than a later ambiguous identity error.
    mesh_ids = [obj.data.as_pointer() for obj in selected]
    _require(len(mesh_ids) == len(set(mesh_ids)),
             "Sources share a mesh datablock; duplicate logical Sections need explicit new IDs")
    return tuple(selected)


def _read_mesh(obj, inverse, scale):
    mesh = obj.data
    for name, (kind, domain) in ATTRIBUTE_SCHEMA.items():
        attribute = mesh.attributes.get(name)
        _require(attribute is not None, f"{obj.name}: required attribute {name} is missing")
        _require(attribute.data_type == kind and attribute.domain == domain,
                 f"{obj.name}: {name} must be {kind} / {domain}")
    transform = inverse @ obj.matrix_world
    if mesh.is_editmode:
        # Reading the live BMesh avoids stale Mesh attribute arrays while a
        # user drags vertices in Edit Mode. Do not leave Edit Mode to evaluate.
        bm = bmesh.from_edit_mesh(mesh)
        bm.verts.ensure_lookup_table()
        bm.edges.ensure_lookup_table()
        bm.verts.index_update()
        bm.edges.index_update()
        roles = bm.verts.layers.int.get("st_endpoint_role")
        ids = bm.edges.layers.int.get("st_section_id")
        widths = bm.edges.layers.float.get("st_width")
        offsets = bm.edges.layers.float.get("st_offset")
        _require(all(layer is not None for layer in (roles, ids, widths, offsets)),
                 f"{obj.name}: live Edit Mode attribute layers are unavailable")
        vertices = tuple(tuple(scale * c for c in (transform @ v.co)) for v in bm.verts)
        edges = tuple(tuple(v.index for v in e.verts) for e in bm.edges)
        source = contract.SourceMesh(obj.name, vertices, edges,
            tuple(e[ids] for e in bm.edges), tuple(e[widths] for e in bm.edges),
            tuple(e[offsets] for e in bm.edges), tuple(v[roles] for v in bm.verts),
            tuple(tuple(v.index for v in f.verts) for f in bm.faces))
    else:
        source = contract.SourceMesh(obj.name,
            tuple(tuple(scale * c for c in (transform @ v.co)) for v in mesh.vertices),
            tuple(tuple(e.vertices) for e in mesh.edges),
            tuple(int(v.value) for v in mesh.attributes["st_section_id"].data),
            tuple(float(v.value) for v in mesh.attributes["st_width"].data),
            tuple(float(v.value) for v in mesh.attributes["st_offset"].data),
            tuple(int(v.value) for v in mesh.attributes["st_endpoint_role"].data),
            tuple(tuple(p.vertices) for p in mesh.polygons))
    return source


def _source_maps(obj, source):
    """Recover indices only after the contract has proved the chains valid."""
    groups = {}
    for edge_index, (edge, section_id) in enumerate(zip(source.edges, source.section_ids)):
        adjacency = groups.setdefault(section_id, {})
        a, b = edge
        adjacency.setdefault(a, []).append((b, edge_index))
        adjacency.setdefault(b, []).append((a, edge_index))
    result = {}
    for section_id, adjacency in groups.items():
        current = next(v for v in adjacency if source.endpoint_roles[v] == 1)
        previous, vertex_indices, edge_indices = None, [], []
        while True:
            vertex_indices.append(current)
            following = [(v, e) for v, e in adjacency[current] if v != previous]
            if not following:
                break
            next_vertex, edge_index = following[0]
            edge_indices.append(edge_index)
            previous, current = current, next_vertex
        result[section_id] = SourceSection(obj, tuple(vertex_indices), tuple(edge_indices))
    return result


def _read_interpolation(obj, *, required=False):
    """Read the native per-edge mode, including a live Edit Mode BMesh.

    v1-v5 sources without this new attribute load with exact-polyline mode 0.
    New v6 inputs must carry it explicitly so missing data is diagnosed rather
    than silently changing a Section's interpolation after topology editing.
    """
    mesh = obj.data
    attribute = mesh.attributes.get(INTERPOLATION_ATTRIBUTE)
    if attribute is None:
        _require(not required, f"{obj.name}: required attribute {INTERPOLATION_ATTRIBUTE} is missing")
        count = len(bmesh.from_edit_mesh(mesh).edges) if mesh.is_editmode else len(mesh.edges)
        return (0,) * count
    _require(attribute.data_type == 'INT' and attribute.domain == 'EDGE',
             f"{obj.name}: {INTERPOLATION_ATTRIBUTE} must be INT / EDGE")
    if mesh.is_editmode:
        bm = bmesh.from_edit_mesh(mesh)
        layer = bm.edges.layers.int.get(INTERPOLATION_ATTRIBUTE)
        _require(layer is not None, f"{obj.name}: live interpolation layer is unavailable")
        values = tuple(edge[layer] for edge in bm.edges)
    else:
        values = tuple(int(item.value) for item in attribute.data)
    _require(all(value in INTERPOLATION_MODES for value in values),
             f"{obj.name}: interpolation must be 0 (exact polyline) or 3 (smooth cubic)")
    return values


def _profile(preset, rise, label):
    _require(preset in ("FLAT", "SMOOTH_CROWN"), label + ": unsupported profile preset")
    rise = _finite(rise, label + " rise")
    _require(rise >= 0, label + ": profile rise cannot be negative")
    _require(preset != "FLAT" or rise == 0., label + ": flat profile requires zero rise")
    return rise


def read_network(controller, scene=None):
    """Read current authored data without changing geometry or logical records.

    Returns a validated CanonicalNetwork plus stable-ID-indexed snapshots and
    transient current source indices. No callers may persist those indices as
    references. Invalid input raises ContractError and must suppress output.
    """
    _require(controller is not None and hasattr(controller, "st_network"),
             "Select a registered street network controller")
    settings = controller.st_network
    _require(settings.enabled, "Object is not an enabled street network controller")
    _require((settings.schema_major, settings.schema_minor) == (SCHEMA_MAJOR, SCHEMA_MINOR),
             "Unsupported street input schema version")
    try:
        UUID(settings.network_uuid)
    except (ValueError, AttributeError):
        raise ContractError("Network requires a valid persistent UUID") from None
    _require(not any(other != controller and other.st_network.enabled
                     and other.st_network.network_uuid == settings.network_uuid
                     for other in bpy.data.objects),
             "Duplicate network UUID: duplicate networks require explicit identity remapping")
    _unit_level(controller.matrix_world, "Network controller")
    scene = scene or bpy.context.scene
    scale = _finite(scene.unit_settings.scale_length, "Scene metre conversion", positive=True)
    matrix = controller.matrix_world.copy()
    inverse = matrix.inverted()
    objects = _sources(controller)
    meshes = tuple(_read_mesh(obj, inverse, scale) for obj in objects)
    interpolations = {obj.as_pointer(): _read_interpolation(
        obj, required=bool(controller.get('st_network_v8', False) or controller.get('st_network_v7', False) or controller.get('st_network_v6', False))) for obj in objects}
    section_records, street_records, intersection_records = {}, [], {}
    connector_records, bundle_records = {}, {}

    def unique(mapping, key, value, label):
        _require(key not in mapping, f"Duplicate {label} ID {key}")
        mapping[key] = value

    for record in settings.sections:
        rise = _profile(record.preset, record.rise, f"Section {record.section_id}")
        clip_start = _finite(record.clip_start, 'Selection boundary start trim')
        clip_end = _finite(record.clip_end, 'Selection boundary end trim')
        _require(min(clip_start, clip_end) >= 0., 'Selection boundary trims must be nonnegative')
        unique(section_records, record.section_id, SectionRecord(record.section_id,
            record.street_id, record.preset, rise, record.profile_reversed,
            clip_start=clip_start, clip_end=clip_end), "Section registry")
    for record in settings.streets:
        for item in record.items:
            _require(item.kind == "SECTION",
                     f"Street {record.street_id}: {item.kind} items are unsupported by this native subset")
        street_records.append(contract.Street(record.street_id,
            tuple((item.section_id, item.forward) for item in record.items)))
    for record in settings.intersections:
        world = Vector(tuple(_finite(v, "Intersection position") / scale for v in record.position))
        position = tuple(float(v) * scale for v in (inverse @ world))
        datum = _finite(record.datum, "Intersection datum") - matrix.translation.z * scale
        unique(intersection_records, record.intersection_id, IntersectionRecord(
            record.intersection_id, position, datum,
            _finite(record.radius, "Intersection radius", positive=True)), "Intersection")
    for record in settings.bundles:
        members = tuple((m.street_id, m.forward, m.head_order, m.tail_order) for m in record.members)
        _require(len(members) == 2, "Initial native Bundle requires two whole member Streets")
        _require(len({m[0] for m in members}) == len(members), "Bundle repeats a Street")
        _require(sorted(m[2] for m in members) == [0, 1]
                 and sorted(m[3] for m in members) == [0, 1], "Bundle head/tail orders must be permutations")
        unique(bundle_records, record.bundle_id, BundleRecord(record.bundle_id, members), "Bundle")
    for record in settings.connectors:
        if record.use_profile_override:
            _profile(record.preset, record.rise, f"Connector {record.connector_id}")
        radius = _finite(record.radius_override, "Corner radius override")
        _require(radius == -1. or radius > 0., "Corner radius override must be -1 or positive")
        members = tuple((m.section_id, m.section_end) for m in record.members)
        lateral = tuple(m.lateral_order for m in record.members)
        _require(sorted(lateral) == list(range(len(members))), "Connector lateral order must be a permutation")
        if record.bundle_id != -1:
            _require(record.use_profile_override and record.separator,
                     "Bundle requires an explicit shared profile and separator plateau")
        else:
            _require(not record.separator, "Separator requires an explicit Bundle")
        unique(connector_records, record.connector_id, ConnectorRecord(
            record.connector_id, record.intersection_id, members, record.bundle_id,
            record.use_profile_override, record.preset, float(record.rise),
            record.separator, radius, record.radius_next_connector_id, lateral), "Connector")
    canonical = contract.canonicalize(meshes, street_records,
        tuple(contract.Intersection(key) for key in intersection_records),
        tuple(contract.Connector(c.id, c.intersection_id, c.members, c.bundle_id)
              for c in connector_records.values()), bundle_ids=tuple(bundle_records))
    ownership = canonical.section_streets()
    _require(set(section_records) == set(ownership),
             "Section registry IDs must exactly match the authored source Sections")
    for section_id, street_id in ownership.items():
        _require(section_records[section_id].street_id == street_id,
                 f"Section {section_id}: registry Street ownership disagrees with Street items")
    from . import transition_bindings
    transition_records = transition_bindings.read(settings, canonical, section_records,
                                                  connector_records, bundle_records)
    streets = {s.id: s for s in canonical.streets}
    for bundle in bundle_records.values():
        _require(all(m[0] in streets for m in bundle.members), "Bundle references a missing Street")
    for connector in connector_records.values():
        if connector.radius_override > 0.:
            target = connector_records.get(connector.radius_next_connector_id)
            _require(target is not None,
                     f"Connector {connector.id}: corner override requires a valid next Connector ID")
            _require(target.id != connector.id,
                     f"Connector {connector.id}: corner override cannot reference itself")
            _require(target.intersection_id == connector.intersection_id,
                     f"Connector {connector.id}: corner override pair must belong to the same Intersection")
            # Existence/ownership are structural checks. Runtime must also
            # verify that the declared next connector is currently adjacent
            # in CCW order before applying this radius to a geometric corner.
        if connector.bundle_id == -1:
            continue
        bundle = bundle_records[connector.bundle_id]
        _require({ownership[s] for s, end in connector.members} == {m[0] for m in bundle.members},
                 "Bundle connector members must match the complete registered member Streets")
        bundle_ends = []
        for section_id, section_end in connector.members:
            street_id = ownership[section_id]
            items = streets[street_id].sections
            start_key = (items[0][0], 0 if items[0][1] else 1)
            end_key = (items[-1][0], 1 if items[-1][1] else 0)
            key = (section_id, section_end)
            _require(key in (start_key, end_key), "Whole-Street Bundle must attach at a Street terminal")
            member = next(m for m in bundle.members if m[0] == street_id)
            bundle_ends.append((key == end_key) ^ (not member[1]))
        _require(len(set(bundle_ends)) == 1, "Bundle members must attach at the same logical Bundle end")
        at_tail = bundle_ends[0]
        expected = {m[0]: m[3] if at_tail else m[2] for m in bundle.members}
        _require(all(expected[ownership[s]] == order for (s, _), order
                     in zip(connector.members, connector.lateral_orders)),
                 "Connector lateral order disagrees with declared Bundle end ordering")
    source_maps = {}
    for obj, mesh in zip(objects, meshes):
        source_maps.update(_source_maps(obj, mesh))
    for section_id, source in source_maps.items():
        values = interpolations[source.object.as_pointer()]
        modes = {values[index] for index in source.edge_indices}
        _require(len(modes) == 1,
                 f"Section {section_id}: interpolation must be constant on every Section edge")
        section_records[section_id] = replace(section_records[section_id], interpolation=modes.pop())
    signature = (settings.network_uuid, canonical.signature(),
        tuple(section_records[key] for key in sorted(section_records)),
        tuple(intersection_records[key] for key in sorted(intersection_records)),
        tuple(connector_records[key] for key in sorted(connector_records)),
        tuple(bundle_records[key] for key in sorted(bundle_records)),
        settings.resolution, _finite(settings.exaggeration, "Exaggeration"),
        _finite(settings.cell_size, "Cell size", positive=True), scale,
        tuple(tuple(float(v) for v in row) for row in matrix),
        tuple(transition_records[key] for key in sorted(transition_records)))
    return NetworkInput(canonical, objects, source_maps, section_records,
        intersection_records, connector_records, bundle_records, scale,
        float(settings.cell_size), matrix, signature, transition_records)
